CREATE TYPE "CampaignStatus" AS ENUM ('active', 'completed');
CREATE TYPE "EmailStatus" AS ENUM ('scheduled', 'processing', 'sent', 'failed');
CREATE TABLE "User" ("id" TEXT NOT NULL, "googleId" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "avatarUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Sender" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT, "host" TEXT NOT NULL, "port" INTEGER NOT NULL, "username" TEXT NOT NULL, "password" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Sender_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Campaign" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "requestedStartTime" TIMESTAMP(3) NOT NULL, "delayMs" INTEGER NOT NULL, "requestedHourlyLimit" INTEGER NOT NULL, "effectiveHourlyLimit" INTEGER NOT NULL, "status" "CampaignStatus" NOT NULL DEFAULT 'active', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Campaign_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ScheduledEmail" ("id" TEXT NOT NULL, "campaignId" TEXT NOT NULL, "senderId" TEXT, "recipient" TEXT NOT NULL, "scheduledTime" TIMESTAMP(3) NOT NULL, "status" "EmailStatus" NOT NULL DEFAULT 'scheduled', "sentAt" TIMESTAMP(3), "failedAt" TIMESTAMP(3), "attempts" INTEGER NOT NULL DEFAULT 0, "messageId" TEXT, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ScheduledEmail_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_googleId_key" ON "User"("googleId"); CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Sender_email_key" ON "Sender"("email");
CREATE INDEX "ScheduledEmail_status_scheduledTime_idx" ON "ScheduledEmail"("status", "scheduledTime");
ALTER TABLE "Campaign" ADD CONSTRAINT "Campaign_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScheduledEmail" ADD CONSTRAINT "ScheduledEmail_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ScheduledEmail" ADD CONSTRAINT "ScheduledEmail_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "Sender"("id") ON DELETE SET NULL ON UPDATE CASCADE;
